/* ============================================
   RenDS — Context Menu Component
   ============================================
   Right-click menu using Popover API.
   Reuses ren-menu styles for items.
   Minimal JS for right-click trigger + positioning.

   Usage:
     <div class="ren-context-menu-trigger" data-context="my-ctx-menu">
       Right-click this area
     </div>

     <div id="my-ctx-menu" class="ren-context-menu" popover>
       <button class="ren-menu-item">Cut</button>
       <button class="ren-menu-item">Copy</button>
       <button class="ren-menu-item">Paste</button>
       <hr class="ren-menu-separator">
       <button class="ren-menu-item ren-menu-item-danger">Delete</button>
     </div>
   ============================================ */

.ren-context-menu {
  /* Reset popover defaults */
  margin: 0;
  padding: 0;
  border: none;
  background: none;
  inset: auto;

  /* Menu appearance (matches ren-menu) */
  background: var(--color-surface);
  border: var(--stroke-1) solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  padding-block: var(--space-1);
  min-width: 10rem;
  max-height: calc(100vh - 32px);
  overflow-y: auto;
  overscroll-behavior: contain;

  /* Position set by JS */
  position: fixed;

  /* Animation — semantic tokens keep context-menu in sync with
     ren-menu / ren-popover. Collapses to 0ms under reduce. */
  opacity: 0;
  transform: scale(0.95);
  transform-origin: top left;
  transition:
    opacity var(--duration-enter) var(--ease-enter),
    transform var(--duration-enter) var(--ease-enter),
    overlay var(--duration-enter) var(--ease-enter) allow-discrete,
    display var(--duration-enter) var(--ease-enter) allow-discrete;
}

.ren-context-menu:popover-open,
.ren-context-menu.ren-open {
  opacity: 1;
  transform: scale(1);
}

@starting-style {
  .ren-context-menu:popover-open {
    opacity: 0;
    transform: scale(0.95);
  }
}

/* ─── Reuse menu item styles ─── */
/* Already defined in ren-menu.css:
   .ren-menu-item, .ren-menu-separator, etc.
   Import ren-menu.css alongside this file.
*/

/* ─── Reduced motion ─── */
@media (prefers-reduced-motion: reduce) {
  .ren-context-menu {
    transition: none;
  }
}


/* ============================================
   RenDS — Context Menu Controller
   ============================================
   Handles right-click trigger, positioning,
   and keyboard navigation.

   Usage:
     import { initContextMenu } from './ren-context-menu.js';
     initContextMenu('my-ctx-menu');

   Or auto-init all:
     import { initAllContextMenus } from './ren-context-menu.js';
     initAllContextMenus();
   ============================================ */

import { createDismissable } from '../../../utils/dismissable.js';

/**
 * @param {string|HTMLElement} menuOrId - The popover element or its ID
 */
export function initContextMenu(menuOrId) {
  const menu = typeof menuOrId === 'string'
    ? document.getElementById(menuOrId)
    : menuOrId;
  if (!menu) return;

  if (menu.dataset.renContextMenuInitialized === 'true') return;
  menu.dataset.renContextMenuInitialized = 'true';
  const controller = new AbortController();
  menu.__renContextController = controller;
  let returnTrigger = null;

  menu.setAttribute('popover', 'manual');
  menu.setAttribute('role', 'menu');
  menu.classList.add('ren-context-menu');

  // Find all triggers for this menu
  const triggers = [...document.querySelectorAll(`[data-context="${menu.id}"]`)];
  const triggerId = menu.getAttribute('trigger-id');
  const explicitTrigger = triggerId ? document.getElementById(triggerId) : null;
  if (explicitTrigger && !triggers.includes(explicitTrigger)) triggers.push(explicitTrigger);
  const itemSelector = [
    '.ren-menu-item:not(:disabled):not([aria-disabled="true"])',
    '[role="menuitem"]:not(:disabled):not([aria-disabled="true"])',
  ].join(', ');

  const isOpen = () => menu.matches(':popover-open') || menu.classList.contains('ren-open');

  // Dismiss behavior (click outside, Escape) runs through the shared layer
  // stack so nested/sibling overlays dismiss innermost-first instead of every
  // open overlay reacting to the same document-level event. `excludeElements`
  // keeps every registered trigger out of "outside"; `triggerElement` is
  // refreshed per open so the layer knows which trigger owns the current
  // instance.
  const dismissLayer = createDismissable(menu, {
    onDismiss: () => close(),
    excludeElements: triggers,
    escapeKey: true,
    clickOutside: true,
  });
  controller.signal.addEventListener('abort', () => dismissLayer.deactivate());

  const close = () => {
    if (!isOpen()) return;

    dismissLayer.deactivate();

    if ('hidePopover' in menu && menu.matches(':popover-open')) {
      try {
        menu.hidePopover();
      } catch {
        // Popover may have already been closed by the browser.
      }
    } else {
      menu.classList.remove('ren-open');
    }

    menu.setAttribute('data-state', 'closed');
    if (returnTrigger && document.contains(returnTrigger)) returnTrigger.focus();
  };

  const show = (x, y, target) => {
    if (isOpen()) {
      close();
    }

    // Position menu at cursor
    menu.style.left = `${x}px`;
    menu.style.top = `${y}px`;

    if ('showPopover' in menu) {
      try {
        menu.showPopover();
      } catch {
        // Popover may already be open during rapid repeated contextmenu events.
      }
    } else {
      menu.classList.add('ren-open');
    }

    menu.setAttribute('data-state', 'open');

    // Safe to activate synchronously: `contextmenu` (and the Shift+F10 /
    // ContextMenu keydown path) always fires after the `pointerdown` of the
    // same gesture, so the layer never sees the pointer event that opened it.
    dismissLayer.updateOptions({ triggerElement: returnTrigger });
    dismissLayer.activate();

    // Adjust if overflows viewport
    const rect = menu.getBoundingClientRect();
    if (rect.right > window.innerWidth) {
      menu.style.left = `${Math.max(8, x - rect.width)}px`;
    }
    if (rect.bottom > window.innerHeight) {
      menu.style.top = `${Math.max(8, y - rect.height)}px`;
    }

    // Focus first item
    const firstItem = menu.querySelector(itemSelector);
    firstItem?.focus();

    menu.dispatchEvent(new CustomEvent('ren-context-menu-open', {
      bubbles: true,
      composed: true,
      detail: { x, y, target },
    }));
  };

  triggers.forEach((trigger) => {
    trigger.addEventListener('contextmenu', (e) => {
      e.preventDefault();
      returnTrigger = trigger;
      show(e.clientX, e.clientY, e.target);
    }, { signal: controller.signal });

    trigger.addEventListener('keydown', (e) => {
      if (e.key !== 'ContextMenu' && !(e.key === 'F10' && e.shiftKey)) return;

      e.preventDefault();
      const rect = trigger.getBoundingClientRect();
      returnTrigger = trigger;
      show(rect.left + 8, rect.bottom + 8, e.target);
    }, { signal: controller.signal });
  });

  // Keyboard navigation inside menu
  menu.addEventListener('keydown', (e) => {
    const items = [...menu.querySelectorAll(itemSelector)];
    if (items.length === 0) return;

    const current = items.indexOf(document.activeElement);

    if (e.key === 'ArrowDown') {
      e.preventDefault();
      items[(current + 1) % items.length]?.focus();
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      items[(current - 1 + items.length) % items.length]?.focus();
    } else if (e.key === 'Home') {
      e.preventDefault();
      items[0]?.focus();
    } else if (e.key === 'End') {
      e.preventDefault();
      items.at(-1)?.focus();
    } else if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      document.activeElement?.click();
      close();
    }
  }, { signal: controller.signal });

  // Close on item click
  menu.addEventListener('click', (e) => {
    if (e.target.closest('.ren-menu-item')) {
      close();
    }
  }, { signal: controller.signal });

  // Outside pointer interactions (including a right-click elsewhere, which is
  // always preceded by a pointerdown) and Escape are owned by the shared
  // dismissable layer above — no component-local document listeners.
}

export function destroyContextMenu(menuOrId) {
  const menu = typeof menuOrId === 'string'
    ? document.getElementById(menuOrId)
    : menuOrId;
  if (!menu) return;
  menu.__renContextController?.abort();
  delete menu.__renContextController;
  delete menu.dataset.renContextMenuInitialized;
}

/**
 * Auto-init all context menus.
 */
export function initAllContextMenus() {
  const menuIds = new Set();
  document.querySelectorAll('[data-context]').forEach((el) => {
    menuIds.add(el.dataset.context);
  });
  menuIds.forEach(initContextMenu);
}

/**
 * Registry-friendly custom element facade over the same controller used by
 * initContextMenu(). There is one behavior owner and one reconnect-safe
 * AbortController regardless of which public entry point consumers use.
 */
export class RenContextMenu extends HTMLElement {
  connectedCallback() {
    if (!this.id) this.id = `ren-context-menu-${Math.random().toString(36).slice(2, 11)}`;
    initContextMenu(this);
  }

  disconnectedCallback() {
    destroyContextMenu(this);
  }
}

if (!customElements.get('ren-context-menu')) {
  customElements.define('ren-context-menu', RenContextMenu);
}

