/**
 * RenDS — Toast Notification System CSS
 * =====================================
 * Styles for notification toasts with animations,
 * positioning, variants, and responsive behavior.
 */

/* ═══ VIEWPORT CONTAINER ═══ */
.ren-toast-viewport {
  position: fixed;
  z-index: var(--z-toast, 9999);
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  max-height: 100dvh;
  overflow: hidden;
  pointer-events: none;
  max-width: min(420px, calc(100vw - 2rem));
}

/* Position variants */
.ren-toast-viewport[data-position="top-right"] {
  top: var(--space-4);
  right: var(--space-4);
  flex-direction: column;
}

.ren-toast-viewport[data-position="top-left"] {
  top: var(--space-4);
  left: var(--space-4);
  flex-direction: column;
}

.ren-toast-viewport[data-position="top-center"] {
  top: var(--space-4);
  left: 50%;
  transform: translateX(-50%);
  flex-direction: column;
}

.ren-toast-viewport[data-position="bottom-right"] {
  bottom: var(--space-4);
  right: var(--space-4);
  flex-direction: column-reverse;
}

.ren-toast-viewport[data-position="bottom-left"] {
  bottom: var(--space-4);
  left: var(--space-4);
  flex-direction: column-reverse;
}

.ren-toast-viewport[data-position="bottom-center"] {
  bottom: var(--space-4);
  left: 50%;
  transform: translateX(-50%);
  flex-direction: column-reverse;
}

/* ═══ TOAST CONTAINER ═══ */
.ren-toast {
  pointer-events: auto;
  background: var(--color-surface-raised);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  padding: var(--space-3) var(--space-4);
  display: flex;
  gap: var(--space-3);
  align-items: flex-start;
  min-width: 20rem;
  max-width: 100%;
  position: relative;
  overflow: hidden;
  /* Enter + exit use semantic tokens so global motion tuning cascades here. */
  animation: ren-toast-fade-in var(--duration-enter) var(--ease-enter);
}

.ren-toast[data-closing] {
  animation: ren-toast-fade-out var(--duration-exit) var(--ease-exit);
  opacity: 0;
}

/* Slide-in animations by position */
.ren-toast-viewport[data-position="top-right"] .ren-toast,
.ren-toast-viewport[data-position="bottom-right"] .ren-toast {
  animation: ren-toast-slide-in-right var(--duration-enter) var(--ease-enter);
}

.ren-toast-viewport[data-position="top-right"] .ren-toast[data-closing],
.ren-toast-viewport[data-position="bottom-right"] .ren-toast[data-closing] {
  animation: ren-toast-slide-out-right var(--duration-exit) var(--ease-exit);
}

.ren-toast-viewport[data-position="top-left"] .ren-toast,
.ren-toast-viewport[data-position="bottom-left"] .ren-toast {
  animation: ren-toast-slide-in-left var(--duration-enter) var(--ease-enter);
}

.ren-toast-viewport[data-position="top-left"] .ren-toast[data-closing],
.ren-toast-viewport[data-position="bottom-left"] .ren-toast[data-closing] {
  animation: ren-toast-slide-out-left var(--duration-exit) var(--ease-exit);
}

.ren-toast-viewport[data-position="top-center"] .ren-toast,
.ren-toast-viewport[data-position="bottom-center"] .ren-toast {
  animation: ren-toast-fade-in var(--duration-enter) var(--ease-enter);
}

/* ═══ TOAST CONTENT STRUCTURE ═══ */
.ren-toast-icon {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  line-height: 1;
}

/* Body wraps title + description + actions */
.ren-toast-body {
  flex: 1;
  min-width: 0;
}

.ren-toast-title {
  font-weight: var(--font-weight-semibold, 600);
  font-size: var(--text-sm);
  line-height: var(--leading-5);
  color: var(--color-text);
  margin: 0;
}

.ren-toast-description {
  font-size: var(--text-xs);
  line-height: 1.5;
  color: var(--color-text-muted);
  margin: var(--space-1) 0 0;
}

.ren-toast-actions {
  display: flex;
  gap: var(--space-2);
  margin-top: var(--space-2);
  flex-wrap: wrap;
}

/* The action button itself (the docs name it .ren-toast-action; we layer it
   on top of the standard .ren-btn variants for consistent styling). */
.ren-toast-action {
  /* Inherits its visual from .ren-btn ren-btn-ghost ren-btn-sm — this rule
     is just a hook for consumers who want to override per-toast. */
}

.ren-toast-close {
  flex-shrink: 0;
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: none;
  border-radius: var(--radius-sm);
  color: var(--color-text-muted);
  cursor: pointer;
  padding: var(--space-1);
  font-size: 18px;
  line-height: 1;
  /* Tactile (hover/focus/press) — uses shared semantic preset */
  transition: var(--transition-tactile);
}

.ren-toast-close:hover {
  background-color: var(--color-surface-hover);
  color: var(--color-text);
}

.ren-toast-close:active {
  background-color: var(--color-surface-active);
}

/* ═══ TOAST VARIANTS ═══ */
/* Success */
.ren-toast-success {
  background: color-mix(in srgb, var(--color-success-subtle) 65%, var(--color-surface-raised));
}

.ren-toast-success .ren-toast-icon {
  color: var(--color-success);
}

/* Error / Danger */
.ren-toast-error,
.ren-toast-danger {
  background: color-mix(in srgb, var(--color-danger-subtle) 65%, var(--color-surface-raised));
}

.ren-toast-error .ren-toast-icon,
.ren-toast-danger .ren-toast-icon {
  color: var(--color-danger);
}

/* Warning */
.ren-toast-warning {
  background: color-mix(in srgb, var(--color-warning-subtle) 65%, var(--color-surface-raised));
}

.ren-toast-warning .ren-toast-icon {
  color: var(--color-warning);
}

/* Info */
.ren-toast-info {
  background: color-mix(in srgb, var(--color-info-subtle) 65%, var(--color-surface-raised));
}

.ren-toast-info .ren-toast-icon {
  color: var(--color-info);
}

/* Loading */
.ren-toast-loading .ren-toast-icon {
  animation: ren-spinner-rotate 0.8s linear infinite;
}

/* ═══ PROGRESS BAR ═══ */
.ren-toast-progress {
  position: absolute;
  bottom: 0;
  left: 0;
  height: 2px;
  background-color: var(--color-accent);
  transition: width linear;
}

/* ═══ SWIPE STATE ═══ */
.ren-toast[data-swiping] {
  transition: none;
}

/* ═══ ANIMATIONS ═══ */
@keyframes ren-toast-slide-in-right {
  from {
    transform: translateX(100%);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}

@keyframes ren-toast-slide-in-left {
  from {
    transform: translateX(-100%);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}

@keyframes ren-toast-slide-out-right {
  from {
    transform: translateX(0);
    opacity: 1;
  }
  to {
    transform: translateX(100%);
    opacity: 0;
  }
}

@keyframes ren-toast-slide-out-left {
  from {
    transform: translateX(0);
    opacity: 1;
  }
  to {
    transform: translateX(-100%);
    opacity: 0;
  }
}

@keyframes ren-toast-fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes ren-toast-fade-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}

@keyframes ren-spinner-rotate {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

/* ═══ REDUCED MOTION ═══
   Belt-and-suspenders: semantic --duration-* already collapse
   to 0ms under reduced-motion (see tokens/semantic/motion.css),
   so the animations above become instant. We keep this block
   to force a plain fade (no slide) as an Apple-HIG alternative,
   and to stop the loading spinner. */
@media (prefers-reduced-motion: reduce) {
  .ren-toast,
  .ren-toast[data-closing],
  .ren-toast-viewport[data-position="top-right"] .ren-toast,
  .ren-toast-viewport[data-position="bottom-right"] .ren-toast,
  .ren-toast-viewport[data-position="top-left"] .ren-toast,
  .ren-toast-viewport[data-position="bottom-left"] .ren-toast,
  .ren-toast-viewport[data-position="top-center"] .ren-toast,
  .ren-toast-viewport[data-position="bottom-center"] .ren-toast {
    animation: ren-toast-fade-in var(--duration-micro) linear !important;
  }

  .ren-toast[data-closing] {
    animation: ren-toast-fade-out var(--duration-micro) linear !important;
  }

  .ren-toast-loading .ren-toast-icon {
    animation: none;
    opacity: 0.6;
  }
}

/* ═══ RESPONSIVE ═══ */
@media (max-width: 640px) {
  .ren-toast-viewport {
    max-width: calc(100vw - 1rem);
    bottom: var(--space-3);
    left: var(--space-2);
    right: var(--space-2);
    width: auto;
  }

  .ren-toast-viewport[data-position="top-right"],
  .ren-toast-viewport[data-position="top-left"],
  .ren-toast-viewport[data-position="top-center"] {
    bottom: auto;
    left: var(--space-2);
    right: var(--space-2);
    width: auto;
    transform: none;
  }

  .ren-toast-viewport[data-position="bottom-right"],
  .ren-toast-viewport[data-position="bottom-left"],
  .ren-toast-viewport[data-position="bottom-center"] {
    bottom: var(--space-3);
    left: var(--space-2);
    right: var(--space-2);
    width: auto;
    transform: none;
  }

  .ren-toast {
    min-width: unset;
    width: 100%;
  }
}
/* Appearance API bridge */
.ren-toast { inline-size: var(--ren-toast-width, 360px); padding: var(--ren-toast-padding, var(--space-4)); border-radius: var(--ren-toast-radius, var(--radius-lg)); background: var(--ren-toast-bg, var(--color-surface-raised)); border-color: var(--ren-toast-border, var(--color-border)); box-shadow: var(--ren-toast-shadow, var(--shadow-lg)); gap: var(--ren-toast-gap, var(--space-3)); animation-duration: var(--ren-toast-anim-duration, var(--duration-normal)); animation-timing-function: var(--ren-toast-easing, var(--ease-out)); }

@media (any-pointer: coarse), (pointer: coarse) {
  .ren-toast-close {
    min-inline-size: var(--touch-min);
    min-block-size: var(--touch-min);
  }
}


/**
 * RenDS — Toast Notification System
 * ==================================
 * Transient notifications anchored to a corner of the viewport.
 *
 * Light DOM only. The viewport is a plain element with class
 * `.ren-toast-viewport` (or the convenience custom element
 * `<ren-toast-viewport>`). Toasts are plain `.ren-toast` divs
 * appended to it.
 *
 * Public API (also available as `window.toast`):
 *   toast.success(title, options?)
 *   toast.info(title, options?)
 *   toast.warning(title, options?)
 *   toast.danger(title, options?)
 *   toast.show(options)            — { title, description, status, duration, action }
 *   toast.dismiss(id)
 *   toast.dismissAll()
 *   toast.promise(promise, { loading, success, error })
 *
 * Options:
 *   title        — required string
 *   description  — optional secondary line
 *   status       — "success" | "info" | "warning" | "danger" | "loading"
 *   duration     — auto-dismiss ms (0 = persistent, default 4000 / 8000 for danger)
 *   dismissible  — show close button (default true)
 *   action       — { label, onClick } inline button
 */

import { t } from '../../../utils/i18n.js';
import { announceAssertive, announcePolite } from '../../../utils/live-region.js';

/* ─── Defaults ─── */

const DEFAULT_DURATIONS = {
  success: 4000,
  info: 4000,
  warning: 5000,
  danger: 8000,
  loading: 0, // persistent
};

const ICONS = {
  success: '✓',
  info: 'ℹ',
  warning: '⚠',
  danger: '✕',
  loading: '⟳',
};

const VALID_POSITIONS = new Set([
  'top-right',
  'top-left',
  'top-center',
  'bottom-right',
  'bottom-left',
  'bottom-center',
]);

/* ─── Custom element (convenience) ─── */

export class RenToastViewport extends HTMLElement {
  connectedCallback() {
    this._listenerController?.abort();
    this._listenerController = new AbortController();
    const { signal } = this._listenerController;

    this.classList.add('ren-toast-viewport');
    if (!this.hasAttribute('data-position')) {
      this.setAttribute('data-position', 'bottom-right');
    }
    if (!VALID_POSITIONS.has(this.getAttribute('data-position'))) {
      this.setAttribute('data-position', 'bottom-right');
    }
    if (!this.hasAttribute('aria-label')) {
      // Resolved at connect time: a setLocale() call after this point does not
      // relabel an already-connected viewport.
      this.setAttribute('aria-label', t('toast.region'));
    }
    if (!this.hasAttribute('role')) this.setAttribute('role', 'region');

    // Pause timers on hover or keyboard focus
    this.addEventListener('mouseenter', () => pauseTimersFor(this), { signal });
    this.addEventListener('mouseleave', () => resumeTimersFor(this), { signal });
    this.addEventListener('focusin', () => pauseTimersFor(this), { signal });
    this.addEventListener('focusout', (e) => {
      if (!this.contains(e.relatedTarget)) resumeTimersFor(this);
    }, { signal });
  }

  disconnectedCallback() {
    this._listenerController?.abort();
    this._listenerController = null;
    resumeTimersFor(this);
  }
}

if (!customElements.get('ren-toast-viewport')) {
  customElements.define('ren-toast-viewport', RenToastViewport);
}

/* ─── Per-viewport timer book-keeping ─── */

const timerStore = new WeakMap(); // viewport → { timers: Map<id, {timerId, remaining, startedAt}>, paused: bool }

function getStore(viewport) {
  let store = timerStore.get(viewport);
  if (!store) {
    store = { timers: new Map(), paused: false };
    timerStore.set(viewport, store);
  }
  return store;
}

function pauseTimersFor(viewport) {
  const store = getStore(viewport);
  if (store.paused) return;
  store.paused = true;
  for (const [id, info] of store.timers.entries()) {
    if (info.timerId == null) continue;
    clearTimeout(info.timerId);
    info.timerId = null;
    if (info.startedAt && info.remaining) {
      info.remaining = Math.max(0, info.remaining - (Date.now() - info.startedAt));
    }
    // Pause progress bar (freeze its current width)
    const toastEl = viewport.querySelector(`[data-toast-id="${CSS.escape(id)}"]`);
    if (toastEl) {
      const progress = toastEl.querySelector('.ren-toast-progress');
      if (progress) {
        const width = getComputedStyle(progress).width;
        progress.style.transition = 'none';
        progress.style.width = width;
      }
    }
  }
}

function resumeTimersFor(viewport) {
  const store = getStore(viewport);
  if (!store.paused) return;
  store.paused = false;
  for (const [id, info] of store.timers.entries()) {
    if (info.remaining > 0) {
      info.startedAt = Date.now();
      info.timerId = setTimeout(() => dismissToast(viewport, id), info.remaining);
      // Resume progress bar
      const toastEl = viewport.querySelector(`[data-toast-id="${CSS.escape(id)}"]`);
      if (toastEl) {
        const progress = toastEl.querySelector('.ren-toast-progress');
        if (progress) {
          // Force reflow then animate to 0
          progress.style.transition = `width ${info.remaining}ms linear`;
          requestAnimationFrame(() => {
            progress.style.width = '0%';
          });
        }
      }
    }
  }
}

/* ─── Viewport resolution ─── */

let _autoViewport = null;

function resolveViewport(preferredId) {
  if (preferredId) {
    const v = document.getElementById(preferredId);
    if (v) return v;
  }
  if (_autoViewport && document.body.contains(_autoViewport)) {
    return _autoViewport;
  }
  // Look for any existing viewport in the page
  const existing = document.querySelector('.ren-toast-viewport, ren-toast-viewport');
  if (existing) {
    _autoViewport = existing;
    return existing;
  }
  // Auto-create
  _autoViewport = document.createElement('ren-toast-viewport');
  _autoViewport.setAttribute('data-position', 'bottom-right');
  document.body.appendChild(_autoViewport);
  return _autoViewport;
}

/* ─── Toast construction ─── */

function generateId() {
  return `toast-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

function normalize(input, statusOverride) {
  const opts = typeof input === 'string' ? { title: input } : { ...input };
  opts.statusExplicit = statusOverride != null || opts.status != null;
  if (statusOverride) opts.status = statusOverride;
  if (!opts.status) opts.status = 'info';
  opts.durationExplicit = opts.duration != null;
  if (opts.duration == null) opts.duration = DEFAULT_DURATIONS[opts.status] ?? 4000;
  if (opts.dismissible == null) opts.dismissible = true;
  return opts;
}

function buildToast(id, opts) {
  const { title, description, status, duration, dismissible, action } = opts;

  const toast = document.createElement('div');
  toast.className = `ren-toast ren-toast-${status}`;
  toast.setAttribute('data-toast-id', id);
  if (duration > 0) toast.setAttribute('data-duration', String(duration));
  toast.setAttribute('role', status === 'danger' ? 'alert' : 'status');
  toast.setAttribute('tabindex', '0'); // focusable for Esc/F6

  // Icon
  const icon = document.createElement('span');
  icon.className = 'ren-toast-icon';
  icon.setAttribute('aria-hidden', 'true');
  icon.textContent = ICONS[status] ?? ICONS.info;
  toast.appendChild(icon);

  // Body (title + description + action)
  const body = document.createElement('div');
  body.className = 'ren-toast-body';

  if (title) {
    const t = document.createElement('p');
    t.className = 'ren-toast-title';
    t.textContent = title;
    body.appendChild(t);
  }

  if (description) {
    const d = document.createElement('p');
    d.className = 'ren-toast-description';
    d.textContent = description;
    body.appendChild(d);
  }

  if (action && action.label) {
    const actions = document.createElement('div');
    actions.className = 'ren-toast-actions';

    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'ren-toast-action ren-btn ren-btn-ghost ren-btn-sm';
    btn.textContent = action.label;
    btn.addEventListener('click', () => {
      try {
        action.onClick?.();
      } finally {
        // Find the host viewport at click time (toast may have moved? unlikely)
        const viewport = toast.closest('.ren-toast-viewport, ren-toast-viewport');
        if (viewport) dismissToast(viewport, id);
      }
    });
    actions.appendChild(btn);
    body.appendChild(actions);
  }

  toast.appendChild(body);

  // Close button
  if (dismissible) {
    const close = document.createElement('button');
    close.type = 'button';
    close.className = 'ren-toast-close';
    // Resolved per toast: each toast.show() picks up the locale active at that
    // moment, so a setLocale() call between toasts is honoured.
    close.setAttribute('aria-label', t('toast.close'));
    close.textContent = '×';
    close.addEventListener('click', () => {
      const viewport = toast.closest('.ren-toast-viewport, ren-toast-viewport');
      if (viewport) dismissToast(viewport, id);
    });
    toast.appendChild(close);
  }

  // Progress bar (auto-dismiss countdown)
  if (duration > 0) {
    const progress = document.createElement('div');
    progress.className = 'ren-toast-progress';
    progress.style.width = '100%';
    progress.style.transition = `width ${duration}ms linear`;
    toast.appendChild(progress);
    requestAnimationFrame(() => {
      progress.style.width = '0%';
    });
  }

  // Esc dismisses when toast itself has focus
  toast.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      const viewport = toast.closest('.ren-toast-viewport, ren-toast-viewport');
      if (viewport) dismissToast(viewport, id);
    }
  });

  return toast;
}

/* ─── Show / dismiss ─── */

function showOnViewport(viewport, opts) {
  const id = opts.id || generateId();

  // If a toast with this id exists, replace it
  const existing = viewport.querySelector(`[data-toast-id="${CSS.escape(id)}"]`);
  if (existing) {
    existing.remove();
    const store = getStore(viewport);
    const t = store.timers.get(id);
    if (t?.timerId) clearTimeout(t.timerId);
    store.timers.delete(id);
  }

  const toast = buildToast(id, opts);
  viewport.appendChild(toast);

  // Resolve the closest effective token scope, including overrides on the
  // generated toast itself. Explicit duration/status options remain
  // authoritative.
  if (!opts.durationExplicit && !opts.statusExplicit) {
    const tokenDuration = getComputedStyle(toast)
      .getPropertyValue('--ren-toast-duration')
      .trim();
    const parsedDuration = parseFloat(tokenDuration);
    if (Number.isFinite(parsedDuration) && parsedDuration >= 0) {
      opts.duration = parsedDuration;
      const progress = toast.querySelector('.ren-toast-progress');
      if (opts.duration > 0) {
        toast.setAttribute('data-duration', String(opts.duration));
        if (progress) progress.style.transition = `width ${opts.duration}ms linear`;
      } else if (progress) {
        progress.remove();
        toast.removeAttribute('data-duration');
      }
    }
  }

  if (!opts.durationExplicit && opts.duration > 0) toast.setAttribute('data-duration', String(opts.duration));

  // Schedule auto-dismiss
  if (opts.duration > 0) {
    const store = getStore(viewport);
    const startedAt = Date.now();
    const timerId = store.paused
      ? null
      : setTimeout(() => dismissToast(viewport, id), opts.duration);
    store.timers.set(id, { timerId, remaining: opts.duration, startedAt });
  }

  // Announce via live region (separate from the toast DOM so SRs don't double-up)
  const announcement = [opts.title, opts.description].filter(Boolean).join('. ');
  if (announcement) {
    if (opts.status === 'danger') announceAssertive(announcement);
    else announcePolite(announcement);
  }

  // Enforce optional max-toasts
  enforceMax(viewport);

  return id;
}

function enforceMax(viewport) {
  const max = parseInt(viewport.getAttribute('data-max'), 10);
  if (!max || isNaN(max)) return;
  const toasts = viewport.querySelectorAll('.ren-toast:not([data-closing])');
  if (toasts.length <= max) return;
  for (let i = 0; i < toasts.length - max; i++) {
    dismissToast(viewport, toasts[i].dataset.toastId);
  }
}

function dismissToast(viewport, id) {
  if (!viewport || !id) return;
  const toast = viewport.querySelector(`[data-toast-id="${CSS.escape(id)}"]`);
  if (!toast) return;

  const store = getStore(viewport);
  const t = store.timers.get(id);
  if (t?.timerId) clearTimeout(t.timerId);
  store.timers.delete(id);

  toast.setAttribute('data-closing', '');

  // Wait for the exit animation, then remove
  const dur = parseFloat(getComputedStyle(toast).animationDuration) * 1000 || 200;
  setTimeout(() => toast.remove(), dur);
}

/* ─── F6: focus viewport globally ─── */

function setupGlobalKeys() {
  if (window.__renToastF6Wired) return;
  window.__renToastF6Wired = true;
  document.addEventListener('keydown', (e) => {
    if (e.key === 'F6') {
      const viewport = document.querySelector('ren-toast-viewport, .ren-toast-viewport');
      if (!viewport) return;
      const firstToast = viewport.querySelector('.ren-toast');
      if (firstToast) {
        e.preventDefault();
        firstToast.focus();
      }
    }
  });
}

setupGlobalKeys();

/* ─── Public API ─── */

function show(input) {
  const opts = normalize(input);
  const viewport = resolveViewport();
  return showOnViewport(viewport, opts);
}

function variantFn(status) {
  return function (title, options = {}) {
    const opts =
      typeof title === 'string'
        ? { ...options, title }
        : { ...title, ...options };
    return show(normalize(opts, status));
  };
}

export const toast = Object.assign(show, {
  show,
  success: variantFn('success'),
  info: variantFn('info'),
  warning: variantFn('warning'),
  danger: variantFn('danger'),
  // Common alias for users coming from other libs
  error: variantFn('danger'),
  loading: variantFn('loading'),

  dismiss(id) {
    const viewport = resolveViewport();
    dismissToast(viewport, id);
  },

  dismissAll() {
    const viewport = resolveViewport();
    viewport.querySelectorAll('.ren-toast:not([data-closing])').forEach((t) => {
      dismissToast(viewport, t.dataset.toastId);
    });
  },

  update(id, updates) {
    const viewport = resolveViewport();
    const toastEl = viewport.querySelector(`[data-toast-id="${CSS.escape(id)}"]`);
    if (!toastEl) return;
    if (updates.status) {
      toastEl.className = `ren-toast ren-toast-${updates.status}`;
      toastEl.setAttribute('data-toast-id', id);
      toastEl.setAttribute(
        'role',
        updates.status === 'danger' ? 'alert' : 'status'
      );
      const icon = toastEl.querySelector('.ren-toast-icon');
      if (icon) icon.textContent = ICONS[updates.status] ?? ICONS.info;
    }
    if (updates.title !== undefined) {
      const t = toastEl.querySelector('.ren-toast-title');
      if (t) t.textContent = updates.title;
    }
    if (updates.description !== undefined) {
      const d = toastEl.querySelector('.ren-toast-description');
      if (d) d.textContent = updates.description;
    }
  },

  promise(promise, options = {}) {
    const id = generateId();
    const loadingOpts = normalize(options.loading || t('toast.promiseLoading'), 'loading');
    loadingOpts.id = id;
    const viewport = resolveViewport();
    showOnViewport(viewport, loadingOpts);

    return promise
      .then((data) => {
        const successInput =
          typeof options.success === 'function'
            ? options.success(data)
            : options.success;
        const successOpts = normalize(successInput || t('toast.promiseSuccess'), 'success');
        successOpts.id = id;
        showOnViewport(viewport, successOpts);
        return data;
      })
      .catch((err) => {
        const errorInput =
          typeof options.error === 'function' ? options.error(err) : options.error;
        const errorOpts = normalize(errorInput || t('toast.promiseError'), 'danger');
        errorOpts.id = id;
        showOnViewport(viewport, errorOpts);
        throw err;
      });
  },
});

// Expose globally — the docs show `window.toast.success(...)` as the primary usage.
if (typeof window !== 'undefined') {
  window.toast = toast;
}

# ren-toggle-group Component Contract

Grouped toggle controls for mutually exclusive or multi-select modes.

Load this file after `ren-design.md` and before generating, editing, or reviewing `ren-toggle-group` UI.

## Purpose

- Provide the agent-facing public contract for the `ren-toggle-group` composite.
- Keep generated markup aligned with the colocated CSS/JS source.
- Route theming through semantic tokens and the component token API instead of ad hoc styles.

## Use When

- You need the Toggle Group composite behavior or visual role.
- The UI should stay inside RenDS' vanilla HTML/CSS/JS conventions.
- The implementation can use the public selectors, states, and imports listed here.

## Do Not Use When

- Native HTML plus `base/primitive-zero.md` is enough.
- A simpler primitive can express the UI without this composite.
- You would need to invent undocumented selectors, states, or JavaScript APIs.

