  flex-direction: column;
  z-index: var(--ren-z-modal, var(--z-modal));
  margin: auto;
  animation: ren-command-in var(--duration-enter) var(--ease-enter);

  @starting-style {
    opacity: 0;
    transform: translate(-50%, -50%) scale(0.98);
  }

