      this._setSubmittingState(false);
      this.dispatchEvent(new CustomEvent('ren-submit-error', {
        detail: { error },
        bubbles: true,
        composed: true,
      }));
      return;
    }

    if (!result.valid) {
      this._isSubmitting = false;
      this.dispatchEvent(
        new CustomEvent('ren-invalid', {
          detail: { errors: result.errors },
          bubbles: true,
          composed: true,
        })
      );
